public void insert(InventItemPriceRefRecId  _inventItemPriceRefRecId)
{
    next insert();

    if (this.METGUPItemBasePriceId)
    {
        GUPItemBasePrice itemBasePrice = GUPItemBasePrice::findRecId(this.METGUPItemBasePriceId, true);

        if (itemBasePrice.RecId && itemBasePrice.METItemPriceActivationStatus != METItemPriceActivationStatus::Completed)
        {
            itemBasePrice.metUpdateActivationStatus(METItemPriceActivationStatus::Completed);
        }
    }
}
